/**
 * Helper Functions
 */

function getDayInfo(dateString) {
  return SPRINT_DAYS_MAP.find(d => d.dateStr === dateString) || null;
}

function getTodayInfo() {
  const now = new Date();
  const dateStr = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
  return getDayInfo(dateStr);
}

function getAllDays() {
  return SPRINT_DAYS_MAP;
}

function getSprintMetadata() {
  return {
    totalDays: 360,
    startDate: 'Wednesday, September 16, 2026 (መስከረም 6, 2019 ዓ.ም.)',
    endDate: 'Friday, September 10, 2027 (ጳጉሜ 5, 2019 ዓ.ም.)',
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    getDayInfo,
    getTodayInfo,
    getAllDays,
    getSprintMetadata,
    SPRINT_START_GREGORIAN,
    SPRINT_END_GREGORIAN
  };
}
